const input = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const body = String(input.body || '').trim();
if (!body) {
  return [{ json: { ok: false, status: 'needs_review', error: 'invalid_input', message: 'Falta el campo obligatorio body.', actions: [] } }];
}
const sentences = body.split(/(?<=[.!?])\s+/).map((item) => item.trim()).filter(Boolean);
const actions = [];
for (const line of body.split(/[\n.;!?]+/)) {
  const clean = line.trim().replace(/^[-*]\s*/, '');
  const match = clean.match(/(?:accion|acción|tarea|pendiente|hacer|necesito|please|need to)\b[:\s-]*(.+)/i);
  if (match && !actions.includes(match[1].trim())) actions.push(match[1].trim());
}
return [{ json: { ok: true, status: 'processed', email_id: String(input.id || 'webhook-email'), sender: String(input.sender || 'desconocido'), subject: String(input.subject || 'Sin asunto'), summary: (sentences.slice(0, 2).join(' ').slice(0, 360) || 'Sin texto suficiente.'), actions: actions.slice(0, 5), action_count: Math.min(actions.length, 5), needs_human_review: actions.length === 0 } }];
